export function translateServerError(lang: Lang, msg: string): string {
  const k = SERVER_ERRORS[msg]
  if (k) return translate(lang, k)
  const m = /^Monthly AI limit reached \((\d+)\/(\d+)\)/.exec(msg)
  if (m) return fmt(translate(lang, 'err.ai_limit'), { used: m[1], limit: m[2] })
  return msg
}
